<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Great Wave - low poly wallpaper</title>
<link href="https://fonts.googleapis.com/css2?family=Shippori+Mincho:wght@600&display=swap" rel="stylesheet">
<style>
  html,body{margin:0;height:100%;overflow:hidden;background:#f0e2c3}
  canvas{display:block}
  #cartouche{position:fixed;left:28px;top:24px;writing-mode:vertical-rl;font-family:'Shippori Mincho',serif;
    font-size:22px;color:#1c3f7a;border:2px solid #1c3f7a;padding:10px 4px;background:#f6f1e3cc;letter-spacing:4px;pointer-events:none}
</style>
</head>
<body>
<div id="cartouche">神奈川沖浪裏</div>
<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

// Palette sampled by eye from the print: cream paper, Prussian blue, pale foam, tan boats.
const C = {
  paper: 0xf0e2c3, horizon: 0x8d8e96,
  deep: 0x1c3f7a, mid: 0x2f6fb3, pale: 0x9fc1d9, foam: 0xf6f1e3,
  boat: 0xc8906b, boatDark: 0x8a5d3d, fujiRock: 0x3d5f93, snow: 0xf4f1e8
};

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(C.paper);
const camera = new THREE.PerspectiveCamera(42, innerWidth / innerHeight, 0.1, 200);
camera.position.set(0, 3.2, 22);
camera.lookAt(0, 2.5, 0);

scene.add(new THREE.HemisphereLight(0xfff4dc, 0x2f6fb3, 1.3));
const sun = new THREE.DirectionalLight(0xfff0d0, 0.9);
sun.position.set(6, 12, 24);
scene.add(sun);

const flat = (color) => new THREE.MeshLambertMaterial({ color, flatShading: true, side: THREE.DoubleSide });

// Sky: grey band at the horizon like the bokashi gradient of the print
const skyGeo = new THREE.PlaneGeometry(90, 40, 1, 16);
const skyCol = [];
const pos = skyGeo.attributes.position;
for (let i = 0; i < pos.count; i++) {
  const t = (pos.getY(i) + 20) / 40;
  const c = new THREE.Color(C.horizon).lerp(new THREE.Color(C.paper), Math.min(1, t * 2.2));
  skyCol.push(c.r, c.g, c.b);
}
skyGeo.setAttribute('color', new THREE.Float32BufferAttribute(skyCol, 3));
const sky = new THREE.Mesh(skyGeo, new THREE.MeshBasicMaterial({ vertexColors: true }));
sky.position.set(0, 10, -40);
scene.add(sky);

// Mount Fuji: small, low, centre, under the hollow of the wave
const fuji = new THREE.Group();
const rock = new THREE.Mesh(new THREE.ConeGeometry(4.5, 2.6, 7), flat(C.fujiRock));
rock.position.y = 1.3;
const snow = new THREE.Mesh(new THREE.ConeGeometry(1.5, 0.9, 7), flat(C.snow));
snow.position.y = 2.17;
fuji.add(rock, snow);
fuji.position.set(2.5, -0.9, -30);
fuji.scale.set(1.3, 1.0, 1);
scene.add(fuji);

// Far sea
const seaGeo = new THREE.PlaneGeometry(90, 40, 70, 30);
seaGeo.rotateX(-Math.PI / 2);
const sea = new THREE.Mesh(seaGeo, flat(C.mid));
sea.position.set(0, -1.2, -8);
scene.add(sea);
const seaBase = seaGeo.attributes.position.array.slice();

// Great wave: tall ridge from a profile swept across X, crest leaning into the hollow
function waveProfile(x, t) {
  const peak = Math.exp(-((x + 0.35) ** 2) * 3.2) * 9.5;
  const ramp = Math.max(0, -x) * 1.4;
  return peak + ramp + Math.sin(x * 9 + t) * 0.15;
}
function buildWave(width, depth, heightScale, color) {
  const g = new THREE.PlaneGeometry(width, depth, 60, 10);
  g.rotateX(-Math.PI / 2);
  const m = new THREE.Mesh(g, flat(color));
  m.userData.base = g.attributes.position.array.slice();
  m.userData.heightScale = heightScale;
  m.userData.width = width;
  return m;
}
function deformWave(mesh, t, curl) {
  const p = mesh.geometry.attributes.position;
  const b = mesh.userData.base;
  for (let i = 0; i < p.count; i++) {
    const x = b[i * 3], z = b[i * 3 + 2];
    const nx = x / (mesh.userData.width / 2);
    const zt = (z + 4) / 8;
    const h = waveProfile(nx, t) * mesh.userData.heightScale * zt;
    const lean = curl * Math.max(0, h - 5) * 0.5;
    p.setXYZ(i, x + lean, h, z);
